// Some portions generated by Claude
import type { Graph } from "./graph-types.ts";
import { INTERNAL_LITERAL_NODE_PREFIX } from "./rdf-terms.ts";
import { LABEL_PROPERTIES } from "./rdf-vocabulary.ts";

export const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";

/**
 * What the Graph view draws. The model keeps every triple; unless values are shown, the canvas draws resources and
 * the links between them: literal values and rdf:type links are left to node colours and the details card, and a
 * class that is only reached through rdf:type disappears with its links. Kept nodes and edges are the model's own
 * objects, so positions written to the model are the canvas positions.
 */
/** What the canvas keeps of an edge list; it depends on the edges alone (literal ids carry their prefix). */
type EdgeScope = { edges: Graph["edges"]; typeTargets: Set<string>; linkedIds: Set<string> };
const edgeScopes = new WeakMap<Graph["edges"], EdgeScope>();
const drawnGraphs = new WeakMap<Graph, Graph>();

function scopeEdges(edges: Graph["edges"], otherLiterals?: ReadonlySet<string>): EdgeScope {
  const literal = (id: string) => id.startsWith(INTERNAL_LITERAL_NODE_PREFIX) || Boolean(otherLiterals?.has(id));
  const typeTargets = new Set<string>();
  const linkedIds = new Set<string>();
  const kept = edges.filter((edge) => {
    if (edge.predicate === RDF_TYPE) {
      typeTargets.add(edge.target);
      return false;
    }
    if (literal(edge.source) || literal(edge.target)) return false;
    linkedIds.add(edge.source);
    linkedIds.add(edge.target);
    return true;
  });
  return { edges: kept, typeTargets, linkedIds };
}

function edgeScope(edges: Graph["edges"]): EdgeScope {
  const cached = edgeScopes.get(edges);
  if (cached) return cached;
  const scope = scopeEdges(edges);
  edgeScopes.set(edges, scope);
  return scope;
}

const LABEL_PROPERTY_SET: ReadonlySet<string> = new Set(LABEL_PROPERTIES);
const drawnGraphsWithValues = new WeakMap<Graph, Graph>();
const titleText = (text: string) => text.trim().normalize("NFC");

/**
 * With values shown: every node and link, except a label value that only repeats the title of the cards it labels.
 * A literal stays when anything else links it, or when one of its subjects shows another title.
 */
function withValues(graph: Graph): Graph {
  const known = drawnGraphsWithValues.get(graph);
  if (known) return known;
  const nodeById = new Map(graph.nodes.map((node) => [node.id, node]));
  const repeatsTitle = new Map<string, boolean>();
  for (const edge of graph.edges) {
    const target = nodeById.get(edge.target);
    if (target?.kind !== "literal") continue;
    const source = nodeById.get(edge.source);
    const title = Boolean(source && LABEL_PROPERTY_SET.has(edge.predicate) && titleText(source.label) === titleText(target.termValue ?? target.label));
    repeatsTitle.set(target.id, (repeatsTitle.get(target.id) ?? true) && title);
  }
  for (const edge of graph.edges) if (repeatsTitle.has(edge.source)) repeatsTitle.set(edge.source, false);
  const hidden = new Set([...repeatsTitle].flatMap(([id, title]) => (title ? [id] : [])));
  const drawn = hidden.size
    ? { ...graph, nodes: graph.nodes.filter((node) => !hidden.has(node.id)), edges: graph.edges.filter((edge) => !hidden.has(edge.target)) }
    : graph;
  drawnGraphsWithValues.set(graph, drawn);
  return drawn;
}

export function canvasGraph(graph: Graph, showValues: boolean): Graph {
  if (showValues) return withValues(graph);
  // The explorer asks for the drawn graph of the same graph many times; on 200,000 edges each pass is noticeable.
  const known = drawnGraphs.get(graph);
  if (known) return known;
  // Literal ids carry their prefix (sparqlNodeId); a graph whose literals do not is filtered without the cache.
  const unprefixedLiterals = new Set(
    graph.nodes.flatMap((node) => (node.kind === "literal" && !node.id.startsWith(INTERNAL_LITERAL_NODE_PREFIX) ? [node.id] : [])),
  );
  const { edges, typeTargets, linkedIds } = unprefixedLiterals.size
    ? scopeEdges(graph.edges, unprefixedLiterals)
    : edgeScope(graph.edges);
  const nodes = graph.nodes.filter(
    (node) => node.kind !== "literal" && (!typeTargets.has(node.id) || linkedIds.has(node.id)),
  );
  const drawn = { nodes, edges, revision: graph.revision, ...(graph.statementLinks ? { statementLinks: graph.statementLinks } : {}) };
  drawnGraphs.set(graph, drawn);
  return drawn;
}
